# Standard library
import uuid
from datetime import date

# Third-party
from sqlalchemy import Date, ForeignKey, Integer, func
from sqlalchemy.orm import Mapped, mapped_column

# Local application
from app.core.base import Base, CreatedMixin, UserScopedMixin


class ProfileSubPoint(CreatedMixin, UserScopedMixin, Base):
    __tablename__ = "profile_sub_point"

    id: Mapped[uuid.UUID] = mapped_column(
        primary_key=True,
        server_default=func.gen_random_uuid(),
        description=(
            "Primary key UUID, auto-generated by the database using "
            "gen_random_uuid()."
        ),
    )
    received_at: Mapped[date] = mapped_column(
        Date,
        nullable=False,
        description=(
            "Calendar date on which the gamification points were awarded to "
            "the user."
        ),
    )
    points: Mapped[int] = mapped_column(
        Integer,
        nullable=False,
        description=(
            "Number of gamification points awarded in this transaction. The "
            "value is positive for earned points; the total is derived from "
            "the reason"
        ),
    )
    reason_id: Mapped[uuid.UUID] = mapped_column(
        ForeignKey("core_ref_point_reason.id"),
        nullable=False,
        description=(
            "Foreign key to core_ref_point_reason identifying why the points "
            "were awarded (e.g. activity completed, achievement earned, POI "
            "visited)."
        ),
    )
    user_achievement_id: Mapped[uuid.UUID | None] = mapped_column(
        ForeignKey("profile_m2m_user_achievement.id", ondelete="SET NULL"),
        description=(
            "Optional foreign key to profile_m2m_user_achievement linking "
            "these points to a specific achievement the user earned. Set to "
            "NULL if the referenced achievement record is deleted."
        ),
    )
    track_id: Mapped[uuid.UUID | None] = mapped_column(
        ForeignKey("explorer_agg_track.id", ondelete="SET NULL"),
        description=(
            "Optional foreign key to explorer_agg_track linking these points "
            "to the recorded GPS track that triggered the award. Set to NULL "
            "if the referenced track is deleted."
        ),
    )
    trip_id: Mapped[uuid.UUID | None] = mapped_column(
        ForeignKey("explorer_agg_trip.id", ondelete="SET NULL"),
        description=(
            "Optional foreign key to explorer_agg_trip linking these points "
            "to the multi-day trip that triggered the award. Set to NULL if "
            "the referenced trip is deleted."
        ),
    )
